func (m *mockEnvironment) MarkWorkProcessStarted(name string) {
	m.processMu.Lock()
	defer m.processMu.Unlock()
	m.processes[name] = true
	m.wg.Add(1)
}

func (m *mockEnvironment) MarkWorkProcessStopped(name string) {
	m.processMu.Lock()
	defer m.processMu.Unlock()
	delete(m.processes, name)
	m.wg.Done()
}

func (m *mockEnvironment) RepeatInBackground(name string, period time.Duration, fun func() bool, skipFirst ...bool) {
	skip := len(skipFirst) > 0 && skipFirst[0]
	go func() {
		if !skip {
			if !fun() {
				return
			}
		}
		ticker := time.NewTicker(period)
		defer ticker.Stop()
		for {
			select {
			case <-m.ctx.Done():
				return
			case <-ticker.C:
				if !fun() {
					return
				}
			}
		}
	}()
}

