func TestTxLoggerModuleBasic(t *testing.T) {
	// Create temp directory for test
	tmpDir, err := os.MkdirTemp("", "txlogger_module_test")
	require.NoError(t, err)
	defer os.RemoveAll(tmpDir)

	// Override the DB path for testing
	originalDBName := global.TxLogDBName
	// We can't easily override the constant, so we'll test with the default path
	// In a real test setup, you'd want to inject the path

	env := newMockEnvironment()
	defer env.Stop()

	// Change to temp directory so the DB is created there
	oldWd, _ := os.Getwd()
	os.Chdir(tmpDir)
	defer os.Chdir(oldWd)

	module := New(env)
	require.NotNil(t, module)
	require.False(t, module.IsEnabled())

	// Enable the logger
	module.TxLogEnable(global.TxLogLevelAllTransactions)
	require.True(t, module.IsEnabled())
	require.Equal(t, global.TxLogLevelAllTransactions, module.Level())

	// Log a transaction
	txid := base.RandomTransactionID(true, 5)
	module.TxLog(time.Now(), "test message", txid)

	// Give the queue time to process
	time.Sleep(100 * time.Millisecond)

	// Read back the record
	shortID := txid.ShortID()
	records, err := module.TxLogGet(shortID[:])
	require.NoError(t, err)
	require.Len(t, records, 1)
	require.Equal(t, "test message", records[0].Message)

	// Disable the logger
	module.TxLogEnable(global.TxLogLevelOff)
	require.False(t, module.IsEnabled())

	// Clean up - restore original path reference
	_ = originalDBName
}

func TestTxLoggerModuleLevelFiltering(t *testing.T) {
	tmpDir, err := os.MkdirTemp("", "txlogger_module_test")
	require.NoError(t, err)
	defer os.RemoveAll(tmpDir)

	env := newMockEnvironment()
	defer env.Stop()

	oldWd, _ := os.Getwd()
	os.Chdir(tmpDir)
	defer os.Chdir(oldWd)

	module := New(env)

	// Enable with branch-only level
	module.TxLogEnable(global.TxLogLevelBranchTransactionsOnly)

	// Create branch and non-branch transactions
	branchTxid := base.RandomTransactionID(true, 5, base.LedgerTime{Slot: 100, Tick: 0}) // branch
	seqTxid := base.RandomTransactionID(true, 5, base.LedgerTime{Slot: 100, Tick: 10})   // seq non-branch
	nonSeqTxid := base.RandomTransactionID(false, 5)                                     // non-sequencer

	// Log all three
	module.TxLog(time.Now(), "branch msg", branchTxid)
	module.TxLog(time.Now(), "seq msg", seqTxid)
	module.TxLog(time.Now(), "non-seq msg", nonSeqTxid)

	time.Sleep(100 * time.Millisecond)

	// Only branch should be logged
	branchShortID := branchTxid.ShortID()
	records, err := module.TxLogGet(branchShortID[:])
	require.NoError(t, err)
	require.Len(t, records, 1, "branch transaction should be logged")

	seqShortID := seqTxid.ShortID()
	records, err = module.TxLogGet(seqShortID[:])
	require.NoError(t, err)
	require.Len(t, records, 0, "non-branch sequencer transaction should not be logged")

	nonSeqShortID := nonSeqTxid.ShortID()
	records, err = module.TxLogGet(nonSeqShortID[:])
	require.NoError(t, err)
	require.Len(t, records, 0, "non-sequencer transaction should not be logged")

	module.Close()
}

func TestTxLoggerModuleBatchLog(t *testing.T) {
	tmpDir, err := os.MkdirTemp("", "txlogger_module_test")
	require.NoError(t, err)
	defer os.RemoveAll(tmpDir)

	env := newMockEnvironment()
	defer env.Stop()

	oldWd, _ := os.Getwd()
	os.Chdir(tmpDir)
	defer os.Chdir(oldWd)

	module := New(env)
	module.TxLogEnable(global.TxLogLevelAllTransactions)

	// Log multiple transactions with single call
	txids := make([]base.TransactionID, 5)
	for i := range txids {
		txids[i] = base.RandomTransactionID(false, byte(i+1))
	}

	module.TxLog(time.Now(), "batch message", txids...)

	time.Sleep(100 * time.Millisecond)

	// Verify each transaction has a record
	for _, txid := range txids {
		shortID := txid.ShortID()
		records, err := module.TxLogGet(shortID[:])
		require.NoError(t, err)
		require.Len(t, records, 1)
		require.Equal(t, "batch message", records[0].Message)
	}

	module.Close()
}
